ists_url":"https://api.github.com/users/masonstevens95/gists{/gist_id}","gravatar_id":"","html_url":"https://github.com/masonstevens95","id":36343085,"login":"masonstevens95","node_id":"MDQ6VXNlcjM2MzQzMDg1","organizations_url":"https://api.github.com/users/masonstevens95/orgs","received_events_url":"https://api.github.com/users/masonstevens95/received_events","repos_url":"https://api.github.com/users/masonstevens95/repos","site_admin":false,"starred_url":"https://api.github.com/users/masonstevens95/starred{/owner}{/repo}","subscriptions_url":"https://api.github.com/users/masonstevens95/subscriptions","type":"User","url":"https://api.github.com/users/masonstevens95","user_view_type":"public"},"comments_url":"https://api.github.com/repos/masonstevens95/picture-to-pixel-art/commits/d8eb43c91328ec139b2c1edd7609917606f07caa/comments","commit":{"author":{"date":"2026-05-06T17:49:12Z","email":"mason.c.stevens@gmail.com","name":"masonstevens95"},"comment_count":0,"committer":{"date":"2026-05-06T17:49:12Z","email":"mason.c.stevens@gmail.com","name":"masonstevens95"},"message":"chore: wire @eslint/js for the flat config + tidy vitest setup typing\n\n@eslint/js was imported by eslint.config.js but missing from\ndevDependencies — pnpm lint failed at import time. Adding it.\n\nAlso nudges vitest.setup.ts ImageData polyfill''s colorSpace from a\nliteral type annotation to ''as const'' so the @typescript-eslint\nprefer-as-const rule is happy.","tree":{"sha":"6a7963298180b4d7bfd1f83f63c6f1a40541c160","url":"https://api.github.com/repos/masonstevens95/picture-to-pixel-art/git/trees/6a7963298180b4d7bfd1f83f63c6f1a40541c160"},"url":"https://api.github.com/repos/masonstevens95/picture-to-pixel-art/git/commits/d8eb43c91328ec139b2c1edd7609917606f07caa","verification":{"payload":null,"reason":"unsigned","signature":null,"verified":false,"verified_at":null}},"committer":{"avatar_url":"https://avatars.githubusercontent.com/u/36343085?v=4","events_url":"https://api.github.com/users/masonste